'use strict';
const priorUpgrade=upgradeSave;
upgradeSave=function(){priorUpgrade();data.goals??=[];data.xpPerLevel??=100;data.quests.forEach(q=>q.policy??={passPercent:100,maxAttempts:0,targetPercent:100,bonusXP:0,bonusCrystals:0,achievement:''})};upgradeSave();
level=function(){return Math.floor(data.xp/data.xpPerLevel)+1};
let aiStatus={configured:false,model:'gpt-4.1-mini'},aiPreview=[],aiBusy=false;
async function localAPI(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});let body;try{body=await response.json()}catch{throw new Error('本機 AI 服務未啟動，請以新版服務開啟遊戲。')}if(!response.ok)throw new Error(body.error||'未能完成請求。');return body}
async function refreshAIStatus(){try{aiStatus=await localAPI('/api/ai/config');const el=$('#ai-connection');if(el)el.textContent=aiStatus.configured?'已設定 · 本次家長登入有效':'未設定 API key';}catch{aiStatus.configured=false}}
function aiSettingsPanel(){setTimeout(refreshAIStatus,0);return `${panelHeading('THE AI SCRIBE','讓 AI 幫手出題，由你決定內容。','API key 只暫存於這部電腦的本機服務，登出或服務重啟就清除。')}<section class="paper admin-panel settings-panel"><h2>OpenAI 連接設定</h2><p class="connection-status" id="ai-connection">檢查連接中…</p><form id="ai-settings-form"><label class="field" for="ai-key">你的 OpenAI API key</label><input class="input" type="password" id="ai-key" name="key" autocomplete="off" spellcheck="false" placeholder="sk-…" required><label class="field" for="ai-model">模型名稱</label><input class="input" id="ai-model" name="model" value="${esc(aiStatus.model)}" required><p class="subtle" style="margin-top:14px">呼叫會使用你自己的 OpenAI API 額度。出題只傳送科目、年級、課題、難度及題數，不傳送姓名、出生年份或成績紀錄。</p><p class="error" id="ai-settings-error" role="alert"></p><div class="inline-actions"><button class="ghost" type="button" data-v3="clear-key">清除 key</button><button class="primary" type="submit">保存本次連接</button></div></form><p class="demo-note">金鑰不會寫入 localStorage、檔案或遊戲匯出資料。示範帳戶請只在本機測試使用。</p></section>`}
function aiComposer(){return `<section class="ai-composer"><div class="panel-title"><h3>${icon('sparkle')} AI 出題助手</h3><button class="ghost small-btn" type="button" data-admin-tab="ai">連接設定</button></div><p class="subtle">描述想練習嘅課題，產生後先預覽、修改，再加入下方題目。</p><label class="field" for="ai-topic">課題與要求</label><textarea class="input" id="ai-topic" maxlength="800" placeholder="例如：小三兩位數乘法，加入兩題生活應用題"></textarea><div class="form-grid"><div><label class="field" for="ai-grade">出題年級</label><select class="input" id="ai-grade">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${Number(data.grade)===n?'selected':''}>小${n}</option>`).join('')}</select></div><div><label class="field" for="ai-difficulty">難度</label><select class="input" id="ai-difficulty"><option>基礎</option><option selected>適中</option><option>進階</option></select></div><div><label class="field" for="ai-count">題數</label><input class="input" id="ai-count" type="number" min="1" max="10" value="5"></div><div><label class="field" for="ai-type">題型</label><select class="input" id="ai-type"><option value="mixed">混合</option><option value="choice">單項選擇</option><option value="text">文字作答</option></select></div></div><p class="error" id="ai-error" role="alert"></p><div class="inline-actions"><button class="ghost small-btn" type="button" data-v3="sample-questions">載入示範題（不呼叫 AI）</button><button class="primary small-btn" type="button" data-v3="generate-ai" id="generate-ai-btn">${icon('sparkle')} 用 AI 產生題目</button></div><div id="ai-preview"></div></section>`}
function policyFields(policy={},prefix='policy'){const p={passPercent:100,maxAttempts:0,targetPercent:100,bonusXP:0,bonusCrystals:0,achievement:'',...policy};return `<fieldset class="reward-policy"><legend>目標、測試次數與達標獎勵</legend><div class="form-grid">${[['passPercent','合格比例（%）',0,100],['maxAttempts','最多作答次數（0＝不限）',0,100],['targetPercent','額外獎勵目標（%）',0,100],['bonusXP','達標額外 EXP',0,100000],['bonusCrystals','達標額外水晶',0,100000]].map(([k,label,min,max])=>`<div><label class="field" for="${prefix}-${k}">${label}</label><input class="input" id="${prefix}-${k}" name="${k}" type="number" min="${min}" max="${max}" value="${p[k]}" required></div>`).join('')}</div><label class="field" for="${prefix}-achievement">達標專屬成就名稱（選填）</label><input class="input" id="${prefix}-achievement" name="achievement" maxlength="60" value="${esc(p.achievement)}" placeholder="例如：中文 70 分小勇者"><p class="subtle">紙本任務嘅分數可以完成後由家長記錄。額外獎勵只發放一次。</p></fieldset>`}
function readPolicy(form){const f=new FormData(form),p={};for(const [k,min,max]of[['passPercent',0,100],['maxAttempts',0,100],['targetPercent',0,100],['bonusXP',0,100000],['bonusCrystals',0,100000]]){const n=bounded(f.get(k),min,max);if(n===null)throw new Error('請檢查目標及獎勵數值。');p[k]=n}p.achievement=String(f.get('achievement')||'').trim().slice(0,60);return p}
const baseMissionPanel=missionPanel;
missionPanel=function(){return baseMissionPanel().replace('<label class="field" for="mission-title">',aiComposer()+'<label class="field" for="mission-title">').replace('<p class="error" id="mission-error"',policyFields()+'<p class="error" id="mission-error"')};
function renderAIPreview(){const el=$('#ai-preview');if(!el)return;el.innerHTML=aiPreview.length?`<div class="preview-heading"><h3>題目草稿 · ${aiPreview.length} 題</h3><span class="mode-tag">尚未派發</span></div>${aiPreview.map((q,i)=>`<div class="ai-preview-card"><strong>第 ${i+1} 題 · ${q.type==='choice'?'選擇題':'文字題'}</strong><p>${esc(q.prompt)}</p>${q.options.map((o,j)=>`<small>${j+1}. ${esc(o)}</small>`).join('')}<details><summary>查看答案與講解</summary><p>${esc(q.type==='choice'?q.options[Number(q.answer)-1]:q.answer)}</p><small>${esc(q.explanation||'')}</small></details><button type="button" class="ghost small-btn" data-drop-preview="${i}">移除此題</button></div>`).join('')}<p class="subtle">請核對內容與答案；加入後可在題目編輯器逐題修改。</p><button class="primary" type="button" data-v3="apply-ai">加入任務題目並編輯</button>`:''}
async function generateAI(){if(aiBusy)return;const count=bounded($('#ai-count').value,1,10),topic=$('#ai-topic').value.trim();if(!count||!topic){$('#ai-error').textContent='請填入課題及 1–10 題。';return}aiBusy=true;$('#generate-ai-btn').disabled=true;$('#generate-ai-btn').textContent='魔法書正在寫題目…';$('#ai-error').textContent='';try{const result=await localAPI('/api/ai/generate',{method:'POST',body:JSON.stringify({subject:$('#mission-subject').value,grade:Number($('#ai-grade').value),topic,count,type:$('#ai-type').value,difficulty:$('#ai-difficulty').value})});aiPreview=result.questions;renderAIPreview()}catch(e){if($('#ai-error'))$('#ai-error').textContent=e.message}finally{aiBusy=false;if($('#generate-ai-btn')){$('#generate-ai-btn').disabled=false;$('#generate-ai-btn').innerHTML=icon('sparkle')+' 用 AI 產生題目'}}}
function grantNamedAchievement(name,desc){if(!name)return;const existing=data.customAchievements.find(a=>a.name===name&&a.rule==='manual');if(existing){existing.granted=true;return}data.customAchievements.push({id:crypto.randomUUID(),name,desc,rule:'manual',target:1,crystals:0,granted:true,claimed:true})}
function applyTargetBonus(q){if(!q.done||q.bonusPaid||!Number.isFinite(q.actualPercent)||q.actualPercent<q.policy.targetPercent)return false;const p=q.policy;q.bonusPaid=true;data.xp+=p.bonusXP;data.crystals+=p.bonusCrystals;grantNamedAchievement(p.achievement,`${q.title}達到 ${p.targetPercent}% 目標`);if(p.bonusXP||p.bonusCrystals||p.achievement)logActivity('achievement',q.title,`達到 ${p.targetPercent}% 目標 · 額外 ${p.bonusXP} EXP`);return true}
awardQuest=function(q,minutes=0){if(q.done)return false;q.done=true;q.status='done';q.completedAt=new Date().toISOString();q.help=false;data.xp+=q.xp;data.crystals+=q.baseCrystals??Math.round(q.xp/2);data.totalMinutes+=Math.max(0,minutes);applyTargetBonus(q);logActivity('complete',q.title,`完成任務 · +${q.xp} EXP`);return true};
function attemptsRemaining(q){return !q.policy.maxAttempts||q.attempts.length<q.policy.maxAttempts}
const baseOpenExerciseV3=openExercise;openExercise=function(q){if(!attemptsRemaining(q)){notify('已完成設定測試次數，請家長調整。');return}baseOpenExerciseV3(q);const form=$('#exercise-form');if(form){const info=document.createElement('p');info.className='exercise-policy-note';info.textContent=`合格 ${q.policy.passPercent}% · 已作答 ${q.attempts.length}${q.policy.maxAttempts?' / '+q.policy.maxAttempts:' 次（不限）'} · 達到 ${q.policy.targetPercent}%：額外 ${q.policy.bonusXP} EXP、${q.policy.bonusCrystals} 水晶${q.policy.achievement?'及「'+q.policy.achievement+'」成就':''}`;form.before(info)}};
const baseStartQuest=startQuest;
startQuest=function(id){const q=data.quests.find(v=>v.id===id);if(q?.mode==='screen'&&!attemptsRemaining(q)){notify('已完成設定嘅測試次數，可以請家長調整或重開。');return}baseStartQuest(id)};
submitExercise=function(form){const q=data.quests.find(v=>v.id===form.dataset.id);if(!q||q.done||q.status==='review'||!attemptsRemaining(q))return;const f=new FormData(form),answers=q.questions.map((_,i)=>String(f.get(`answer-${i}`)||'').trim());if(answers.some(v=>!v))return;const results=q.questions.map((v,i)=>evaluateQuestion(v,answers[i]));const secs=(q.exerciseSeconds||0)+(exerciseSession?(Date.now()-exerciseSession.started)/1000:0);q.attempts.push({at:new Date().toISOString(),answers,results,seconds:secs});q.score=results.filter(v=>v===true).length;q.draftAnswers=answers;exerciseSession=null;q.exerciseSeconds=0;data.totalMinutes+=Math.round(secs/60);logActivity('submit',q.title,`交卷 · ${q.attempts.length} 次作答`);if(results.includes(null)){q.status='review';persist();render();openModal('result','<p class="empty">答案已送到公會長手上，批改後就會記錄分數及獎勵。</p><button class="primary" data-action="close">返屋企</button>','交卷完成');return}q.actualPercent=Math.round(q.score/q.questions.length*100);if(q.actualPercent>=q.policy.passPercent){awardQuest(q,0);persist();render();show('treasure');notify(`完成練習 · ${q.actualPercent} 分！經驗值及達標獎勵已發放。`)}else{q.help=true;q.status='active';persist();openModal('result',`<h3 class="result-title">今次 ${q.actualPercent} 分 · 合格目標 ${q.policy.passPercent} 分</h3><p class="empty">${attemptsRemaining(q)?'重溫之後，可以再試。':'已完成設定測試次數，請家長幫你檢視。'}</p>${q.questions.map((v,i)=>`<div class="review-answer"><strong>第 ${i+1} 題 · ${results[i]?'答啱':'需要重溫'}</strong><p>${esc(v.prompt)}</p><small>${esc(v.explanation||'')}</small></div>`).join('')}${attemptsRemaining(q)?`<button class="primary" data-retry-exercise="${q.id}">重新挑戰</button>`:'<button class="primary" data-action="close">返屋企</button>'}`,'試煉回顧')}};
finishQuest=function(mode){if(!timer||elapsed()<timer.total)return;const q=data.quests.find(v=>v.id===timer.id);clearInterval(timer.handle);timer=null;data.timerDraft=null;if(mode==='complete'){awardQuest(q,q.minutes);persist();render();show('treasure');notify(`任務完成！+${q.xp} EXP。紙本分數可由家長記錄。`)}else{q.help=mode==='help';data.totalMinutes+=q.minutes;logActivity(mode,q.title,mode==='help'?'需要家長幫手':'完成一部分');persist();render();show('quests')}};
const baseReviewQuest=reviewQuest;
reviewQuest=function(id){baseReviewQuest(id);const q=data.quests.find(v=>v.id===id);const m=$('.modal');if(!q||!m)return;const extra=document.createElement('section');extra.className='parent-score-editor';extra.innerHTML=`<h3 class="small-heading">家長評分及任務設定</h3><label class="field" for="review-score">實際分數（百分制）</label><input class="input" type="number" min="0" max="100" id="review-score" value="${q.actualPercent??''}" placeholder="例如 70"><form id="edit-mission-form" data-id="${q.id}"><div class="form-grid"><div><label class="field" for="edit-xp">基本 EXP</label><input class="input" id="edit-xp" name="xp" type="number" min="0" max="1000000" value="${q.xp}" required></div><div><label class="field" for="edit-crystals">基本水晶</label><input class="input" id="edit-crystals" name="crystals" type="number" min="0" max="1000000" value="${q.baseCrystals??Math.round(q.xp/2)}" required></div></div>${policyFields(q.policy,'edit-policy')}<button class="primary" type="submit">儲存設定及分數</button><p class="subtle">已發放嘅基本獎勵唔會重發；未發放嘅達標獎勵會按最新分數核對。</p></form>`;const actions=m.querySelector('.inline-actions');if(actions)m.insertBefore(extra,actions);else m.append(extra)};
function readReviewScore(q){const el=$('#review-score');if(!el||el.value===''){notify('請先填寫實際分數，再確認完成。');el?.focus();return false}const score=bounded(el.value,0,100);if(score===null)return false;q.actualPercent=score;if(score<q.policy.passPercent){notify('未達家長設定嘅合格分數，可以退回重溫或先調整合格目標。');return false}return true}
const baseParentBossPanel=parentBossPanel;
parentBossPanel=function(){return baseParentBossPanel().replace('id="boss-form"','id="trial-form"').replace('<div class="form-end">',`<div class="form-grid">${[['minQuests','最低完成任務數',0,10000,0],['targetScore','目標考試分數',0,100,70],['rewardXP','完成考試基本 EXP',0,100000,50],['bonusXP','達標額外 EXP',0,100000,100],['bonusCrystals','達標額外水晶',0,100000,5]].map(([k,label,min,max,val])=>`<div><label class="field" for="trial-${k}">${label}</label><input class="input" name="${k}" id="trial-${k}" type="number" min="${min}" max="${max}" value="${val}" required></div>`).join('')}</div><label class="field" for="trial-achievement">達標成就名稱（選填）</label><input class="input" name="achievement" id="trial-achievement" maxlength="60" placeholder="例如：中文 70 分勇者"><div class="form-end">`)};
function bossEligible(b){return data.xp>=b.threshold&&data.quests.filter(q=>q.done).length>=(b.minQuests||0)}
bossCards=function(parent=false){return data.bosses.map(b=>{const ready=bossEligible(b),done=data.quests.filter(q=>q.done).length;return `<article class="boss-card"><div class="boss-emblem"><img src="assets/forest-dragon.png" alt="森林守護巨龍"></div><div class="boss-info"><span class="section-kicker">${b.defeated?'TRIAL COMPLETE':ready?'READY TO CHALLENGE':'PREPARING'}</span><h3>${esc(b.name)}</h3><p>${esc(b.description)}</p><small>${esc(b.date)} · 官方目標 ${b.targetScore??70} 分</small><div class="boss-progress"><span style="width:${Math.min(100,data.xp/b.threshold*100)}%"></span></div><p>${data.xp} / ${b.threshold} EXP · 完成任務 ${done} / ${b.minQuests||0}</p>${b.studentTarget!==undefined?`<p>我的目標：${b.studentTarget} 分（獎勵由家長設定）</p>`:''}${b.defeated?`<p class="checkmark">已完成考試 · ${b.actualScore??'未記錄'} 分</p>`:parent?`<button class="primary small-btn" data-defeat-boss="${b.id}" ${ready?'':'disabled'}>記錄考試分數及完成</button>`:`<button class="primary small-btn" data-challenge-boss="${b.id}" ${ready?'':'disabled'}>挑戰 Boss</button>`}${parent?`<button class="ghost small-btn" data-edit-trial="${b.id}">調整目標及獎勵</button>`:`<button class="ghost small-btn" data-student-target="${b.id}">設定我的分數目標</button>`}</div></article>`}).join('')||'<p class="empty">等公會長召喚下一位考試 Boss。</p>'};
function openBossResult(b){if(!bossEligible(b)){notify('仲未達到 EXP 或任務準備要求。');return}openModal('boss-result',`<form id="boss-result-form" data-id="${b.id}"><h3>${esc(b.name)}</h3><p class="subtle">官方目標 ${b.targetScore??70} 分；由家長記錄真實成績。</p><label class="field" for="boss-actual">實際考試分數（0–100）</label><input class="input" id="boss-actual" name="score" type="number" min="0" max="100" required><button class="primary" type="submit" style="margin-top:20px">確認成績及發放獎勵</button></form>`,'考試成績')}
function controlsPanel(){return `${panelHeading('YOUR CHILD, YOUR RULES','成長節奏，由你設定。','每位小朋友都唔同。調整累積 EXP 同升級速度，會保留完整修改紀錄。')}<section class="paper admin-panel settings-panel"><form id="progress-settings-form"><label class="field" for="total-xp">目前累積 EXP</label><input class="input" id="total-xp" name="xp" type="number" min="0" max="10000000" value="${data.xp}" required><label class="field" for="level-step">每級所需 EXP</label><input class="input" id="level-step" name="step" type="number" min="1" max="1000000" value="${data.xpPerLevel}" required><label class="field" for="change-reason">調整原因</label><input class="input" id="change-reason" name="reason" maxlength="200" placeholder="例如：按孩子程度調整" required><button class="primary" type="submit" style="margin-top:22px">儲存成長設定</button></form><p class="demo-note">目前 Lv.${level()}。任務數、重試次數、分數目標與獎勵，可在任務詳情及 Boss 設定調整。</p></section>`}
function goalEditor(g={}){return `<form id="parent-goal-form" ${g.id?`data-id="${g.id}"`:''}><label class="field" for="goal-name">目標名稱</label><input class="input" id="goal-name" name="name" maxlength="80" value="${esc(g.name||'')}" placeholder="例如：中文測驗考 70 分" required><div class="form-grid"><div><label class="field" for="goal-subject">科目</label><select class="input" id="goal-subject" name="subject">${['中文','英文','數學','常識','閱讀','其他'].map(s=>`<option ${s===g.subject?'selected':''}>${s}</option>`).join('')}</select></div><div><label class="field" for="goal-target">目標分數</label><input class="input" id="goal-target" name="target" type="number" min="0" max="100" value="${g.target??70}" required></div><div><label class="field" for="goal-xp">達標 EXP</label><input class="input" id="goal-xp" name="xp" type="number" min="0" max="100000" value="${g.xp??50}" required></div><div><label class="field" for="goal-crystals">達標水晶</label><input class="input" id="goal-crystals" name="crystals" type="number" min="0" max="100000" value="${g.crystals??5}" required></div></div><label class="field" for="goal-achievement">達標成就（選填）</label><input class="input" id="goal-achievement" name="achievement" maxlength="60" value="${esc(g.achievement||'')}"><button class="primary" type="submit" style="margin-top:20px">${g.id?'確認目標及獎勵':'建立目標'}</button></form>`}
function parentGoalsPanel(){return `${panelHeading('DREAMS INTO MILESTONES','小朋友定方向，家長安排獎勵。','學生可以提出分數目標，由家長核准、修改及記錄真實成績。')}<div class="guild-grid"><section class="paper admin-panel"><h2>建立分數目標</h2>${goalEditor()}</section><section class="paper admin-panel"><h2>目標紀錄</h2>${goalCards(true)}</section></div>`}
function goalCards(parent=false){return data.goals.map(g=>`<div class="goal-card"><span class="mode-tag">${g.paid?'已達標領獎':g.approved?'正式目標':'小朋友提議 · 待家長確認'}</span><h3>${esc(g.name)}</h3><p>${esc(g.subject)} · 目標 ${g.target} 分${g.actual!==undefined?` · 實際 ${g.actual} 分`:''}</p>${g.approved?`<small>達標：${g.xp} EXP · ${g.crystals} 水晶${g.achievement?' · '+esc(g.achievement):''}</small>`:''}${parent&&!g.paid?`<div class="inline-actions"><button class="ghost small-btn" data-edit-goal="${g.id}">核准／修改</button>${g.approved?`<button class="primary small-btn" data-grade-goal="${g.id}">記錄成績</button>`:''}</div>`:''}</div>`).join('')||'<p class="empty">定一個做得到嘅小目標，慢慢向前。</p>'}
const prevRoomV3=room;room=function(){return prevRoomV3().replace('<footer class="room-footer">','<button class="hotspot h-goals" data-v3="child-goals">'+icon('star')+' 我的目標</button><footer class="room-footer">')};
function openChildGoals(){openModal('child-goals',`<p class="subtle">你可以提出自己想達到嘅分數，獎勵由家長決定。</p>${goalCards()}<form id="student-goal-form"><label class="field" for="student-goal-name">我想做到…</label><input class="input" id="student-goal-name" name="name" maxlength="80" placeholder="中文測驗想考 70 分" required><div class="form-grid"><div><label class="field" for="student-goal-subject">科目</label><select class="input" id="student-goal-subject" name="subject">${['中文','英文','數學','常識','閱讀','其他'].map(s=>`<option>${s}</option>`).join('')}</select></div><div><label class="field" for="student-goal-score">我嘅目標分數</label><input class="input" id="student-goal-score" name="target" type="number" min="0" max="100" value="70" required></div></div><button class="primary" type="submit" style="margin-top:18px">交俾公會長</button></form>`,'我的成長目標')}
function payGoal(g){if(!g.approved||g.paid||!Number.isFinite(g.actual)||g.actual<g.target)return false;g.paid=true;data.xp+=g.xp;data.crystals+=g.crystals;grantNamedAchievement(g.achievement,g.name);logActivity('achievement',g.name,`達標 ${g.actual} 分 · +${g.xp} EXP`);return true}
const missionSubmissions=new WeakMap();
document.addEventListener('submit',async e=>{
 const form=e.target,f=new FormData(form);
 if(form.id==='login-form'&&role==='parent'){
  e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button[type="submit"]');button.disabled=true;
  try{const result=await localAPI('/api/parent/login',{method:'POST',body:JSON.stringify({username:String(f.get('username')).trim(),password:f.get('password')})});activateFamily(result.profile);sessionRole='parent';adminTab='overview';go('admin');refreshAIStatus()}catch(err){$('#login-error').textContent=err.message;button.disabled=false}return;
 }
 if(form.id==='login-form'&&role==='child'){e.preventDefault();e.stopImmediatePropagation();try{const result=await localAPI('/api/child/login',{method:'POST',body:JSON.stringify({username:String(f.get('username')).trim(),password:f.get('password')})});aiStatus.configured=false;activateFamily(result.profile);if(data.hero!==null&&data.hero!==undefined&&data.hero>=heroes.length){data.hero=0;persist()}chosen=data.hero??0;sessionRole='child';go(data.hero===null?'select':'room')}catch(err){$('#login-error').textContent=err.message}return;}
 if(form.id==='mission-form'&&sessionRole==='parent'){
  try{missionSubmissions.set(form,{policy:readPolicy(form),ids:new Set(data.quests.map(q=>q.id))})}catch(err){e.preventDefault();e.stopImmediatePropagation();$('#mission-error').textContent=err.message}return;
 }
},true);
document.addEventListener('submit',async e=>{
 const form=e.target,id=form.id;
 if(id==='mission-form'){const saved=missionSubmissions.get(form),q=data.quests.at(-1);if(saved&&q&&!saved.ids.has(q.id)){q.policy=saved.policy;persist()}return}
 const ids=['ai-settings-form','edit-mission-form','trial-form','boss-result-form','progress-settings-form','parent-goal-form','student-goal-form','goal-result-form','student-boss-target-form','edit-trial-form'];if(!ids.includes(id))return;e.preventDefault();const f=new FormData(form);
 if(id==='student-goal-form'&&sessionRole==='child'){const target=bounded(f.get('target'),0,100),name=String(f.get('name')).trim();if(target===null||!name)return;data.goals.push({id:crypto.randomUUID(),name,subject:f.get('subject'),target,approved:false,paid:false,proposedBy:'child'});logActivity('goal',name,`小朋友提出 ${target} 分目標`);persist();openChildGoals();notify('目標已送到公會長，等家長確認獎勵。');return}
 if(id==='student-boss-target-form'&&sessionRole==='child'){const b=data.bosses.find(v=>v.id===form.dataset.id),target=bounded(f.get('target'),0,100);if(b&&target!==null){b.studentTarget=target;logActivity('goal',b.name,`小朋友希望考 ${target} 分`);persist();closeModal();notify('你嘅分數目標已記錄，家長可以睇到。')}return}
 if(sessionRole!=='parent')return;
 if(id==='ai-settings-form'){
  const key=$('#ai-key').value;const error=$('#ai-settings-error');const button=form.querySelector('button[type="submit"]');button.disabled=true;error.textContent='';
  try{aiStatus=await localAPI('/api/ai/config',{method:'POST',body:JSON.stringify({key,model:f.get('model')})});$('#ai-key').value='';await refreshAIStatus();notify('本次 AI 連接已保存，未有呼叫 AI。')}catch(err){error.textContent=err.message}finally{button.disabled=false}return;
 }
 if(id==='edit-mission-form'){
  const q=data.quests.find(v=>v.id===form.dataset.id);if(!q)return;try{const policy=readPolicy(form),xp=bounded(f.get('xp'),0,1000000),crystals=bounded(f.get('crystals'),0,1000000);if(xp===null||crystals===null)return;const score=$('#review-score').value;if(score!==''&&bounded(score,0,100)===null)return;q.policy=policy;q.xp=xp;q.baseCrystals=crystals;if(score!=='')q.actualPercent=Number(score);applyTargetBonus(q);logActivity('settings',q.title,'家長調整任務目標、獎勵或分數');persist();render();notify('設定已保存，未領取嘅達標獎勵已核對。')}catch(err){notify(err.message)}return;
 }
 if(id==='trial-form'){
  const n=k=>Number(f.get(k));if(bounded(f.get('threshold'),1,1000000)===null)return;data.bosses.push({id:crypto.randomUUID(),name:String(f.get('name')).trim(),description:String(f.get('description')).trim(),date:f.get('date'),threshold:n('threshold'),reward:n('reward'),minQuests:n('minQuests'),targetScore:n('targetScore'),rewardXP:n('rewardXP'),bonusXP:n('bonusXP'),bonusCrystals:n('bonusCrystals'),achievement:String(f.get('achievement')).trim(),defeated:false});logActivity('boss',f.get('name'),'家長設定考試門檻、目標分數及達標獎勵');persist();render();notify('Boss 目標及獎勵已設定。');return;
 }
 if(id==='boss-result-form'){
  const b=data.bosses.find(v=>v.id===form.dataset.id),score=bounded(f.get('score'),0,100);if(!b||b.defeated||!bossEligible(b)||score===null)return;b.actualScore=score;b.defeated=true;b.completedAt=new Date().toISOString();data.crystals+=b.reward;data.xp+=b.rewardXP||0;if(score>=(b.targetScore??70)){data.xp+=b.bonusXP||0;data.crystals+=b.bonusCrystals||0;grantNamedAchievement(b.achievement,`${b.name} 達到 ${b.targetScore??70} 分`)}logActivity('complete',b.name,`家長記錄 ${score} 分 · ${score>=(b.targetScore??70)?'達標獎勵已發放':'完成考試，繼續成長'}`);persist();render();notify('成績已記錄，對應獎勵已發放。');return;
 }
 if(id==='progress-settings-form'){
  const xp=bounded(f.get('xp'),0,10000000),step=bounded(f.get('step'),1,1000000),reason=String(f.get('reason')).trim();if(xp===null||step===null||!reason)return;const before=data.xp;data.xp=xp;data.xpPerLevel=step;logActivity('settings','家長調整成長進度',`${before} → ${xp} EXP；每級 ${step} EXP。${reason}`);persist();render();notify('成長設定已更新。');return;
 }
 if(id==='parent-goal-form'){
  const target=bounded(f.get('target'),0,100),xp=bounded(f.get('xp'),0,100000),crystals=bounded(f.get('crystals'),0,100000);if([target,xp,crystals].some(v=>v===null))return;let g=data.goals.find(v=>v.id===form.dataset.id);if(g?.paid)return;if(!g){g={id:crypto.randomUUID(),paid:false,proposedBy:'parent'};data.goals.push(g)}Object.assign(g,{name:String(f.get('name')).trim(),subject:f.get('subject'),target,xp,crystals,achievement:String(f.get('achievement')).trim(),approved:true});logActivity('goal',g.name,'家長核准目標及達標獎勵');persist();render();notify('正式目標及獎勵已確認。');return;
 }
 if(id==='goal-result-form'){
  const g=data.goals.find(v=>v.id===form.dataset.id),score=bounded(f.get('score'),0,100);if(!g||!g.approved||g.paid||score===null)return;g.actual=score;const paid=payGoal(g);logActivity('goal',g.name,`家長記錄 ${score} 分`);persist();render();notify(paid?'恭喜達標！額外 EXP、獎勵及成就已發放。':'成績已記錄，未達目標可以繼續努力。');return;
 }
 if(id==='edit-trial-form'){
  const b=data.bosses.find(v=>v.id===form.dataset.id);if(!b||b.defeated)return;for(const k of['threshold','minQuests','targetScore','rewardXP','bonusXP','bonusCrystals','reward']){const max=k==='targetScore'?100:1000000,min=k==='threshold'?1:0;if(bounded(f.get(k),min,max)===null)return;b[k]=Number(f.get(k))}b.achievement=String(f.get('achievement')).trim();logActivity('settings',b.name,'家長調整考試門檻及獎勵');persist();render();notify('Boss 設定已更新。');return;
 }
});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.action==='logout'){aiStatus.configured=false;localAPI('/api/parent/logout',{method:'POST',body:'{}'}).catch(()=>{});return}
 if(b.dataset.v3==='generate-ai'&&sessionRole==='parent'){generateAI();return}
 if(b.dataset.v3==='clear-key'&&sessionRole==='parent'){try{await localAPI('/api/ai/config',{method:'DELETE'});aiStatus.configured=false;refreshAIStatus();notify('API key 已從本機服務清除。')}catch(err){notify(err.message)}return}
 if(b.dataset.v3==='sample-questions'&&sessionRole==='parent'){$('#ai-error').textContent='';aiPreview=[{type:'choice',prompt:'小明有 12 粒糖，平均分給 3 位朋友，每位有幾多粒？',options:['3 粒','4 粒','6 粒'],answer:'2',explanation:'12 ÷ 3 = 4。'},{type:'text',prompt:'24 + 18 = ?',options:[],answer:'42',explanation:'24 + 10 + 8 = 42。'}];renderAIPreview();notify('已載入兩題示範題，未有呼叫 AI。');return}
 if(b.dataset.dropPreview!==undefined&&sessionRole==='parent'){aiPreview.splice(Number(b.dataset.dropPreview),1);renderAIPreview();return}
 if(b.dataset.v3==='apply-ai'&&sessionRole==='parent'){
  readQuestionDrafts();if(questionDraft.length===1&&!questionDraft[0].prompt.trim())questionDraft=[];if(questionDraft.length+aiPreview.length>20){notify('任務最多 20 題，請先移除部分題目。');return}questionDraft.push(...aiPreview.map(q=>({...q})));$('#mission-mode').value='screen';$('#question-builder').hidden=false;drawQuestionDrafts();aiPreview=[];renderAIPreview();notify('草稿已加入題目編輯器，核對後再派發。');return;
 }
 if(b.dataset.v3==='child-goals'&&sessionRole==='child'){openChildGoals();return}
 if(b.dataset.editGoal&&sessionRole==='parent'){const g=data.goals.find(v=>v.id===b.dataset.editGoal);if(g&&!g.paid)openModal('goal-edit',goalEditor(g),'確認目標及獎勵');return}
 if(b.dataset.gradeGoal&&sessionRole==='parent'){const g=data.goals.find(v=>v.id===b.dataset.gradeGoal);if(g&&g.approved&&!g.paid)openModal('goal-score',`<h3>${esc(g.name)}</h3><p class="subtle">目標 ${g.target} 分</p><form id="goal-result-form" data-id="${g.id}"><label class="field" for="goal-actual">實際分數</label><input class="input" id="goal-actual" name="score" type="number" min="0" max="100" required><button class="primary" type="submit" style="margin-top:20px">記錄成績</button></form>`,'記錄目標成績');return}
 if(b.dataset.studentTarget&&sessionRole==='child'){const boss=data.bosses.find(v=>v.id===b.dataset.studentTarget);if(boss)openModal('student-target',`<h3>${esc(boss.name)}</h3><form id="student-boss-target-form" data-id="${boss.id}"><label class="field" for="my-boss-target">我希望考幾多分？</label><input class="input" type="number" id="my-boss-target" name="target" min="0" max="100" value="${boss.studentTarget??70}" required><p class="subtle">你嘅個人目標會畀家長睇到，正式獎勵由家長安排。</p><button class="primary" type="submit" style="margin-top:20px">記錄我的目標</button></form>`,'我的考試目標');return}
 if(b.dataset.editTrial&&sessionRole==='parent'){const boss=data.bosses.find(v=>v.id===b.dataset.editTrial);if(!boss||boss.defeated)return;openModal('trial-edit',`<h3>${esc(boss.name)}</h3><form id="edit-trial-form" data-id="${boss.id}"><div class="form-grid">${[['threshold','所需累積 EXP',boss.threshold],['minQuests','最低完成任務數',boss.minQuests||0],['targetScore','目標分數',boss.targetScore??70],['rewardXP','完成考試 EXP',boss.rewardXP||0],['reward','完成考試水晶',boss.reward],['bonusXP','達標額外 EXP',boss.bonusXP||0],['bonusCrystals','達標額外水晶',boss.bonusCrystals||0]].map(([k,label,value])=>`<div><label class="field" for="trial-edit-${k}">${label}</label><input class="input" name="${k}" id="trial-edit-${k}" type="number" min="${k==='threshold'?1:0}" max="${k==='targetScore'?100:1000000}" value="${value}" required></div>`).join('')}</div><label class="field" for="trial-edit-achievement">達標成就</label><input class="input" name="achievement" id="trial-edit-achievement" value="${esc(boss.achievement||'')}" maxlength="60"><button class="primary" type="submit" style="margin-top:20px">儲存 Boss 設定</button></form>`,'調整 Boss 試煉');return}
},true);
// The hero walks for about 80% of each room cycle, then pauses briefly for a
// storybook pose.  The Level 1 walk sheet supplies the in-between leg frames.
let actorMotion=null, actorPoseTimer=null;
startRoomAnimation=function(){
 clearTimeout(actorMotion);clearTimeout(actorPoseTimer);
 const actor=$('#room-actor');if(!actor)return;
 const stops=[{x:34,y:78,action:'reading'},{x:63,y:82,action:'eating'},{x:73,y:80,action:'practicing'},{x:41,y:78,action:'sitting'},{x:58,y:83,action:'greeting'},{x:47,y:79,action:'resting'}];
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 let index=0,position={x:51,y:80};
 actor.style.left=position.x+'%';actor.style.top=position.y+'%';
 function cycle(){
  if(!document.contains(actor))return;
  if(modal){actorMotion=setTimeout(cycle,1500);return}
  const stop=stops[index++%stops.length];
  const facing=stop.x<position.x?' facing-left':'';
  actor.className='room-actor grounded storybook-actor stepping'+facing;
  actor.style.setProperty('--facing','1');
  $('#actor-prop').innerHTML='';$('#actor-bubble').classList.remove('show');
  if(!reduce){actor.style.left=stop.x+'%';actor.style.top=stop.y+'%'}
  position=stop;
  actorPoseTimer=setTimeout(()=>{
   if(!document.contains(actor)||modal)return;
   actor.className=`room-actor grounded storybook-actor ${stop.action}${facing}`;
   showRoomDialogue($('#actor-bubble'));
  },reduce?0:7600);
  actorMotion=setTimeout(cycle,9500);
 }
 actorMotion=setTimeout(cycle,100);
};
render();
